{
  "propositions": [
    {
      "text": "Regulation (EU) 2021/1119 is the European Climate Law in its consolidated version.",
      "exactQuote": "Regulation (EU) 2021/1119 — European Climate Law (consolidated version)",
      "blockId": "c-climate-002#block-0"
    },
    {
      "text": "The content is sourced from EUR-Lex, the official EU law database.",
      "exactQuote": "Content sourced from EUR-Lex (https://eur-lex.europa.eu/eli/reg/2021/1119/oj), official EU law database.",
      "blockId": "c-climate-002#block-2"
    },
    {
      "text": "The full text of the regulation is publicly available.",
      "exactQuote": "Full text publicly available.",
      "blockId": "c-climate-002#block-2"
    },
    {
      "text": "The consolidated version is as of 2026-04-07.",
      "exactQuote": "Consolidated version as of 2026-04-07.",
      "blockId": "c-climate-002#block-2"
    },
    {
      "text": "The regulation was adopted on 30 June 2021.",
      "exactQuote": "Adopted: 30 June 2021",
      "blockId": "c-climate-002#block-3"
    },
    {
      "text": "The regulation was published in the Official Journal L 243 on 9 July 2021, pages 1-17.",
      "exactQuote": "Published in OJ: L 243, 9 July 2021, pp. 1-17",
      "blockId": "c-climate-002#block-3"
    },
    {
      "text": "The regulation is also known as the 'European Climate Law'.",
      "exactQuote": "Also known as: \"European Climate Law\"",
      "blockId": "c-climate-002#block-3"
    },
    {
      "text": "Union-wide greenhouse gas emissions and removals regulated in Union law shall be balanced within the Union at the latest by 2050.",
      "exactQuote": "Union-wide greenhouse gas emissions and removals regulated in Union law shall be balanced within the Union at the latest by 2050",
      "blockId": "c-climate-002#block-5"
    },
    {
      "text": "Balancing emissions and removals reduces emissions to net zero by 2050.",
      "exactQuote": "thus reducing emissions to net zero by that date",
      "blockId": "c-climate-002#block-5"
    },
    {
      "text": "The Union shall aim to achieve negative emissions after 2050.",
      "exactQuote": "and the Union shall aim to achieve negative emissions thereafter.",
      "blockId": "c-climate-002#block-5"
    },
    {
      "text": "Relevant Union institutions and Member States shall take necessary measures at Union and national level to enable collective achievement of the climate-neutrality objective.",
      "exactQuote": "The relevant Union institutions and the Member States shall take the necessary measures at Union and national level, respectively, to enable the collective achievement of the climate-neutrality objective set out in paragraph 1",
      "blockId": "c-climate-002#block-6"
    },
    {
      "text": "The measures shall take into account the importance of promoting fairness and solidarity among Member States and cost-effectiveness.",
      "exactQuote": "taking into account the importance of promoting both fairness and solidarity among Member States and cost-effectiveness in achieving this objective.",
      "blockId": "c-climate-002#block-6"
    },
    {
      "text": "The binding Union 2030 climate target is a domestic reduction of net greenhouse gas emissions by at least 55% compared to 1990 levels by 2030.",
      "exactQuote": "the binding Union 2030 climate target shall be a domestic reduction of net greenhouse gas emissions (emissions after deduction of removals) by at least 55 % compared to 1990 levels by 2030.",
      "blockId": "c-climate-002#block-8"
    },
    {
      "text": "When implementing the 2030 target, relevant Union institutions and Member States shall prioritise swift and predictable emission reductions and enhance removals by natural sinks.",
      "exactQuote": "When implementing the target referred to in the first subparagraph, the relevant Union institutions and the Member States shall prioritise swift and predictable emission reductions and, at the same time, enhance removals by natural sinks.",
      "blockId": "c-climate-002#block-9"
    },
    {
      "text": "The contribution of net removals to the Union 2030 climate target is limited to 225 million tonnes of CO2 equivalent.",
      "exactQuote": "the contribution of net removals to the Union 2030 climate target shall be limited to 225 million tonnes of CO2 equivalent.",
      "blockId": "c-climate-002#block-10"
    },
    {
      "text": "A Union-wide climate target for 2040 shall be set with a view to achieving the climate-neutrality objective.",
      "exactQuote": "With a view to achieving the climate-neutrality objective set out in Article 2(1) of this Regulation, a Union-wide climate target for 2040 shall be set.",
      "blockId": "c-climate-002#block-12"
    },
    {
      "text": "The Commission shall make a legislative proposal to amend the Regulation to include the Union 2040 climate target at the latest within six months of the first global stocktake under the Paris Agreement.",
      "exactQuote": "To that end, at the latest within six months of the first global stocktake referred to in Article 14 of the Paris Agreement, the Commission shall make a legislative proposal, as appropriate, based on a detailed impact assessment, to amend this Regulation to include the Union 2040 climate target.",
      "blockId": "c-climate-002#block-12"
    },
    {
      "text": "A European Scientific Advisory Board on Climate Change is established.",
      "exactQuote": "A European Scientific Advisory Board on Climate Change (the 'Advisory Board') is hereby established.",
      "blockId": "c-climate-002#block-14"
    },
    {
      "text": "The Advisory Board shall be composed of 15 senior scientific experts covering a broad range of relevant disciplines.",
      "exactQuote": "The Advisory Board shall be composed of 15 senior scientific experts covering a broad range of relevant disciplines.",
      "blockId": "c-climate-002#block-14"
    },
    {
      "text": "No more than two members of the Advisory Board shall hold the nationality of the same Member State.",
      "exactQuote": "No more than two members of the Advisory Board shall hold the nationality of the same Member State.",
      "blockId": "c-climate-002#block-14"
    },
    {
      "text": "The independence of the members of the Advisory Board shall be beyond doubt.",
      "exactQuote": "The independence of the members of the Advisory Board shall be beyond doubt.",
      "blockId": "c-climate-002#block-14"
    }
  ]
}
